package com.luci.pianoroom;
/** General MIDI program names, shared by both banks; original labels stay visible. */
public final class InstrumentCatalog {
 public static final String[] FAMILIES={"Pianos","Sinos e mallets","Órgãos","Guitarras","Baixos","Cordas","Orquestra","Metais","Sopros","Flautas","Synth lead","Pads","Texturas","Étnicos","Percussão","Efeitos","Baterias"};
 private static final String[] GM=("Piano de cauda|Piano brilhante|Piano elétrico de cauda|Piano honky-tonk|Piano elétrico Rhodes|Piano elétrico FM|Cravo|Clavinet|Celesta|Glockenspiel|Caixa de música|Vibrafone|Marimba|Xilofone|Sinos tubulares|Dulcimer|Órgão Hammond|Órgão percussivo|Órgão rock|Órgão de tubos|Órgão de palheta|Acordeão|Harmônica|Bandoneon|Violão nylon|Violão aço|Guitarra jazz|Guitarra limpa|Guitarra abafada|Guitarra overdrive|Guitarra distorcida|Harmônicos de guitarra|Baixo acústico|Baixo elétrico dedo|Baixo elétrico palheta|Baixo fretless|Baixo slap 1|Baixo slap 2|Baixo synth 1|Baixo synth 2|Violino|Viola|Violoncelo|Contrabaixo|Cordas tremolo|Cordas pizzicato|Harpa|Tímpanos|Conjunto de cordas|Cordas lentas|Cordas synth 1|Cordas synth 2|Coral ah|Vozes ooh|Voz synth|Hit de orquestra|Trompete|Trombone|Tuba|Trompete com surdina|Trompa|Seção de metais|Metais synth 1|Metais synth 2|Sax soprano|Sax alto|Sax tenor|Sax barítono|Oboé|Corne inglês|Fagote|Clarinete|Flautim|Flauta transversal|Flauta doce|Flauta de pan|Sopro de garrafa|Shakuhachi|Apito|Ocarina|Synth lead quadrado|Synth lead serra|Synth calliope|Synth chiff|Synth charang|Synth voz|Synth quintas|Synth baixo + lead|Pad fantasia|Pad quente|Pad polysynth|Pad coral|Pad arco|Pad metálico|Pad halo|Pad sweep|Textura chuva|Textura trilha sonora|Textura cristal|Textura atmosfera|Textura brilho|Textura duendes|Textura ecos|Textura ficção científica|Sitar|Banjo|Shamisen|Koto|Kalimba|Gaita de foles|Rabeca|Shanai|Sino tinkle|Agogô|Steel drums|Bloco de madeira|Taiko|Tom melódico|Bateria synth|Prato invertido|Ruído de traste|Respiração|Mar|Pássaros|Telefone|Helicóptero|Aplausos|Disparo").split("\\|");
 public static int guessProgram(String title){String s=title.toLowerCase(java.util.Locale.ROOT);if(s.contains("pad")||s.contains("worship"))return 89;if(s.contains("texture")||s.contains("textura")||s.contains("atmosphere")||s.contains("soundscape"))return 99;if(s.contains("string")||s.contains("cordas"))return 48;if(s.contains("orchestra")||s.contains("orquestra")||s.contains("choir")||s.contains("coral"))return 52;if(s.contains("percussion")||s.contains("percussão"))return 112;String[] words={"rhodes","organ","órgão","guitar","violão","guitarra","violin","violino","cello","violoncelo","bass","baixo","clarinet","clarinete","flute","flauta","trumpet","trompete","sax","harp","harpa","pad","synth","marimba","drum","bateria"};int[] programs={4,16,16,24,24,24,40,40,42,42,32,32,71,71,73,73,56,56,65,46,46,89,80,12,118,118};for(int i=0;i<words.length;i++)if(s.contains(words[i]))return programs[i];return 0;}
 public static int family(int bank,int program){return bank>=128?16:Math.max(0,Math.min(15,program/8));}
 public static String name(String original,int bank,int program,boolean singlePiano){if(singlePiano)return "Piano de cauda YDP";if(bank>=128)return "Bateria · "+original;if(program>=0&&program<128)return GM[program]+(bank==0?"":" · variação "+bank);return original;}
 public static int art(int bank,int program,boolean piano){return 20+(piano?0:family(bank,program));}
}
